2	
3	import java.util.ArrayList;
4	import java.util.Comparator;
5	import java.util.LinkedHashMap;
6	import java.util.List;
7	import java.util.Map;
8	
9	/**
10	 * 成绩排名纯逻辑：依据选手原始耗时与处罚列表计算榜单，不涉及数据库与时间。
11	 *
12	 * <p>规则：
13	 * <ul>
14	 *   <li>总耗时=原始完赛耗时+全部未撤销 ADD_TIME 加时之和；</li>
15	 *   <li>存在未撤销 DISQUALIFY 处罚时状态 DISQUALIFIED，不排名，全部撤销后恢复计算；</li>
16	 *   <li>原始耗时缺失（null）时状态 UNTIMED，不排名；</li>
17	 *   <li>正常选手按总耗时升序，同耗时同名次，下一名次跳过并列人数（1、1、3）；</li>
18	 *   <li>并列者及未排名者内部均按参赛号字典序展示。</li>
19	 * </ul>
20	 */
21	public final class ResultCalculator {
22	
23	    private ResultCalculator() {
24	    }
25	
26	    /**
27	     * 计算即时成绩。
28	     *
29	     * @param runnerView 全部选手视图（参赛号、原始完赛耗时）
30	     * @param penalties  全部处罚（含已撤销）
31	     * @return 按展示顺序排列的成绩条目
32	     */
33	    public static List<ResultEntry> compute(
34	            List<? extends RunnerView> runnerView,
35	            List<? extends PenaltyView> penalties) {
36	        Map<String, Aggregate> aggregates = new LinkedHashMap<>();
37	        for (RunnerView runner : runnerView) {
38	            aggregates.put(runner.bib(), new Aggregate(runner.bib(), runner.finishTimeMs()));
