56	    @Test
57	    void 完整主流程_登记加时取消撤销到封榜快照() {
58	        RaceResponse race = (RaceResponse) raceService.createRace(
59	                new CreateRaceRequest(RACE, "req-create")).body();
60	        assertThat(race.version()).isEqualTo(1);
61	        assertThat(race.status()).isEqualTo(RaceStatus.OPEN);
62	
63	        // v2: 登记选手 a，无成绩
64	        raceService.registerRunner(RACE,
65	                new RegisterRunnerRequest("a", null, 1, "req-reg-a"));
66	        // v3: 登记选手 b=1000ms
67	        raceService.registerRunner(RACE,
68	                new RegisterRunnerRequest("b", 1000L, 2, "req-reg-b"));
69	        // v4: 登记选手 c=1000ms
70	        raceService.registerRunner(RACE,
71	                new RegisterRunnerRequest("c", 1000L, 3, "req-reg-c"));
72	
73	        StandingResponse beforeRevise = raceService.getResults(RACE);
74	        assertThat(beforeRevise.entries()).extracting(ResultEntryResponse::bib)
75	                .containsExactly("b", "c", "a");
76	        assertThat(beforeRevise.entries()).extracting(ResultEntryResponse::status)
77	                .containsExactly(EntryStatus.RANKED, EntryStatus.RANKED, EntryStatus.UNTIMED);
78	
79	        // v5: a 计时修订 1000ms，三人并列
80	        raceService.reviseTime(RACE, new ReviseTimeRequest("a", 1000L, 4, "req-time-a"));
81	        StandingResponse tied = raceService.getResults(RACE);
82	        assertThat(tied.entries()).extracting(ResultEntryResponse::bib)
83	                .containsExactly("a", "b", "c");
84	        assertThat(tied.entries()).extracting(ResultEntryResponse::rank)
85	                .containsExactly(1, 1, 1);
86	        assertThat(tied.version()).isEqualTo(5);
87	
88	        // v6: b 加时 500ms -> 1500ms 排第3
89	        raceService.addPenalty(RACE, new AddPenaltyRequest(
90	                "p-1", "b", "ADD_TIME", 500L, 5, "req-pen-b"));
91	        StandingResponse afterPenalty = raceService.getResults(RACE);
92	        assertThat(afterPenalty.entries()).extracting(ResultEntryResponse::bib)
93	                .containsExactly("a", "c", "b");
94	        assertThat(afterPenalty.entries()).extracting(ResultEntryResponse::rank)
95	                .containsExactly(1, 1, 3);
96	        assertThat(afterPenalty.entries().get(2).penaltyMs()).isEqualTo(500L);
97	        assertThat(afterPenalty.entries().get(2).totalTimeMs()).isEqualTo(1500L);
98	
99	        // v7: c 取消资格 -> b 升为第2，c 不排名
100	        raceService.addPenalty(RACE, new AddPenaltyRequest(
101	                "p-2", "c", "DISQUALIFY", null, 6, "req-dq-c"));
102	        StandingResponse dq = raceService.getResults(RACE);
103	        assertThat(dq.entries()).extracting(ResultEntryResponse::bib)
104	                .containsExactly("a", "b", "c");
105	        assertThat(dq.entries()).extracting(ResultEntryResponse::rank)
106	                .containsExactly(1, 2, null);
107	        assertThat(dq.entries().get(2).status()).isEqualTo(EntryStatus.DISQUALIFIED);
108	
109	        // v8: 撤销 c 的取消资格 -> c 恢复且与 a 并列第1
110	        raceService.revokePenalty(RACE, "p-2",
111	                new RevokePenaltyRequest(7, "req-revoke-dq"));
112	        StandingResponse restored = raceService.getResults(RACE);
113	        assertThat(restored.entries()).extracting(ResultEntryResponse::bib)
114	                .containsExactly("a", "c", "b");
115	        assertThat(restored.entries()).extracting(ResultEntryResponse::rank)
116	                .containsExactly(1, 1, 3);
117	
118	        // v9: 封榜
119	        ServiceResult sealed = raceService.sealRace(RACE,
120	                new SealRaceRequest(8, "req-seal"));
121	        StandingResponse sealedStanding = (StandingResponse) sealed.body();
122	        assertThat(sealed.status()).isEqualTo(200);
123	        assertThat(sealedStanding.status()).isEqualTo(RaceStatus.SEALED);
124	        assertThat(sealedStanding.sealedAt()).isEqualTo(FixedClockTestConfig.FIXED_INSTANT.toEpochMilli());
125	        assertThat(sealedStanding.version()).isEqualTo(9);
126	
127	        StandingResponse snapshot = raceService.getSnapshot(RACE);
128	        assertThat(snapshot).usingRecursiveComparison().isEqualTo(sealedStanding);
129	    }
