public record ConfigureRelayRequest(
        @NotNull @Min(2) @Max(8) Integer legCount,
        @NotNull @Min(1) @Max(10_000) Integer handoffLimitMs,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

